import React, { useState } from 'react';
import MessagesList from '../components/Messages/MessagesList';
import ChatWindow from '../components/Messages/ChatWindow';
import { Menu, X } from 'lucide-react';

const MessagesPage = () => {
  const [showChat, setShowChat] = useState(false);
  const [selectedMessage, setSelectedMessage] = useState(null);

  return (
    <>
      <div className="mb-4 md:mb-6">
        <h1 className="text-xl md:text-2xl font-bold text-neutral-900 dark:text-white">Messages</h1>
        <p className="text-sm md:text-base text-neutral-600 dark:text-neutral-400">Gérez vos conversations</p>
      </div>

      <div className="relative">
        {/* Bouton pour afficher le chat sur mobile */}
        <button
          onClick={() => setShowChat(!showChat)}
          className="md:hidden fixed bottom-6 right-6 z-30 h-12 w-12 rounded-full bg-gradient-to-r from-primary-500 to-secondary-500 text-white shadow-lg flex items-center justify-center"
        >
          {showChat ? <X className="h-5 w-5" /> : <Menu className="h-5 w-5" />}
        </button>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-4 md:gap-6">
          {/* Liste des messages */}
          <div className={`lg:col-span-1 ${showChat ? 'hidden md:block' : 'block'}`}>
            <MessagesList 
              onSelectMessage={(message) => {
                setSelectedMessage(message);
                setShowChat(true);
              }}
            />
          </div>

          {/* Fenêtre de chat */}
          <div className={`lg:col-span-2 ${showChat ? 'block' : 'hidden md:block'}`}>
            {selectedMessage ? (
              <ChatWindow message={selectedMessage} />
            ) : (
              <div className="bg-gradient-to-br from-white to-white/70 dark:from-neutral-900 dark:to-neutral-900/70 backdrop-blur-xl rounded-2xl shadow-lg border border-white/30 dark:border-neutral-800/50 p-6 h-full flex items-center justify-center">
                <div className="text-center">
                  <div className="h-16 w-16 rounded-full bg-gradient-to-r from-primary-500/10 to-secondary-500/10 flex items-center justify-center mx-auto mb-4">
                    <Menu className="h-8 w-8 text-primary-500" />
                  </div>
                  <h3 className="font-bold text-neutral-900 dark:text-white mb-2">Sélectionnez une conversation</h3>
                  <p className="text-neutral-600 dark:text-neutral-400">Choisissez un message pour commencer à discuter</p>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </>
  );
};

export default MessagesPage;
